import {tax,RULES,taxDetail} from './engine.js?v=39';
export const COMP_DEFAULTS={age:30,years:30,own:4000,employer:3000,salary:50000,otherOwn:0,otherEmployer:0,otherSales:0,inflation:1,pensioner:0,dipRate:7,dpsRate:7,dipEntry:3,dipFee:2.16,dpsEntry:0,dpsFee:1,dpsPerformance:15,netReturns:0,loyalty:0,loyaltyRate:0,dipTax:'test',payout:'lump',strategy:'custom',stress:0,shockYear:20,dipShock:-15,dpsShock:-35};
export const COMP_EXAMPLE={...COMP_DEFAULTS,dipRate:7,dpsRate:7,dipFee:1.5,dpsFee:1,dpsPerformance:15,netReturns:0,strategy:'permanent'};
export function cleanComparison(raw={}){const s={...COMP_DEFAULTS};for(const k in s){if(['dipTax','payout','strategy'].includes(k))continue;const n=Number(raw[k]??s[k]);if(Number.isFinite(n))s[k]=n;}const limits={age:[18,90],years:[1,50],own:[0,100000],employer:[0,100000],salary:[0,1000000],otherOwn:[0,48000],otherEmployer:[0,1000000],otherSales:[0,1000000000],inflation:[0,30],dipRate:[-100,100],dpsRate:[-100,100],dipEntry:[0,100],dpsEntry:[0,100],dipFee:[0,20],dpsFee:[0,20],dpsPerformance:[0,50],netReturns:[0,1],pensioner:[0,1],loyalty:[0,1],loyaltyRate:[0,20],stress:[0,1],shockYear:[1,50],dipShock:[-100,100],dpsShock:[-100,100]};for(const [k,[a,b]] of Object.entries(limits))s[k]=Math.min(b,Math.max(a,s[k]));for(const k of ['age','years','netReturns','pensioner','loyalty','stress','shockYear'])s[k]=Math.round(s[k]);s.shockYear=Math.min(s.years,s.shockYear);s.strategy=['custom','equal','permanent'].includes(raw.strategy)?raw.strategy:'custom';s.dipTax=['test','exempt','taxable'].includes(raw.dipTax)?raw.dipTax:'test';s.payout=raw.payout==='pension'?'pension':'lump';return s;}
export function compare(raw){const s=cleanComparison(raw),eligible=s.years>=10&&s.age+s.years>=60,available=Math.max(0,48000-s.otherOwn),excess=Math.max(0,s.employer*12-Math.max(0,50000-s.otherEmployer));
 const base=s.salary*12+Math.max(0,s.otherEmployer-50000)+excess-s.otherOwn;
 const incomeTax=amount=>Math.max(0,Math.min(Math.max(0,amount),RULES.threshold)*.15+Math.max(0,amount-RULES.threshold)*.23-RULES.taxCredit);
 const savings=deduct=>tax(base)-tax(base-Math.min(available,deduct));
 const annualTax={dip:savings(s.own*12),dps:savings(Math.max(0,s.own-(s.pensioner?0:1700))*12)};
 const support=s.pensioner||s.own<500?0:Math.min(340,s.own*.2),points=[{year:0,dip:0,dps:0,dipReal:0,dpsReal:0}];
 const run=kind=>{const state=kind==='dps'?support:0,entry=s[kind+'Entry']/100,fee=s.netReturns?0:s[kind+'Fee']/100,performance=s.netReturns||kind==='dip'?0:s.dpsPerformance/100;let v=0,entryCosts=0,management=0,perf=0,annualProfit=0,nav=1,peak=1,maxDrawdown=0;const cohorts=[],rows=[];
 for(let month=1;month<=s.years*12;month++){const year=Math.ceil(month/12),annualReturn=s.stress&&year===s.shockYear?s[kind+'Shock']:s[kind+'Rate'],m=Math.pow(1+annualReturn/100,1/12)-1,growth=v*m,cost=(v+growth)*fee/12,factor=(1+m)*(1-fee/12);v=Math.max(0,v*factor);nav*=factor;peak=Math.max(peak,nav);maxDrawdown=Math.max(maxDrawdown,peak>0?1-nav/peak:0);for(const c of cohorts)c.value*=factor;management+=cost;annualProfit+=growth-cost;const e=(s.own+s.employer)*entry,deposit=s.own+s.employer+state-e;entryCosts+=e;v+=deposit;cohorts.push({month,value:deposit,cost:s.own+s.employer+state});
 if(month%12===0){const p=Math.min(v,Math.max(0,annualProfit)*performance);if(v>0)nav*=1-p/v;v-=p;peak=Math.max(peak,nav);maxDrawdown=Math.max(maxDrawdown,peak>0?1-nav/peak:0);perf+=p;annualProfit=0;const year=month/12,own=s.own*month,employer=s.employer*month,government=state*month,paid=own+employer+government;
 let taxableGain=Math.max(0,v-paid);if(kind==='dip'&&s.dipTax==='exempt')taxableGain=0;if(kind==='dip'&&s.dipTax==='test')taxableGain=v+s.otherSales<=100000?0:Math.max(0,cohorts.filter(c=>month-c.month<=36).reduce((a,c)=>a+c.value-c.cost,0));
 const dipBase=base-Math.min(available,s.own*12),exitTax=kind==='dps'?(s.payout==='pension'?0:taxableGain*.15):incomeTax(dipBase+taxableGain)-incomeTax(dipBase),net=v-exitTax,taxSaving=annualTax[kind]*year,total=net+taxSaving;
 rows.push({year,annualReturn,value:v,own,employer,state:government,gain:v-paid,entry:entryCosts,management,performance:perf,fees:entryCosts+management+perf,tax:exitTax,net,taxSaving,total,real:total/Math.pow(1+s.inflation/100,year),taxableGain,maxDrawdown});}
 }return {rows,end:rows.at(-1),maxDrawdown};};
 const dip=run('dip'),dps=run('dps');for(let i=0;i<s.years;i++)points.push({year:i+1,dip:dip.rows[i].total,dps:dps.rows[i].total,dipReal:dip.rows[i].total/Math.pow(1+s.inflation/100,i+1),dpsReal:dps.rows[i].total/Math.pow(1+s.inflation/100,i+1)});
 let loyalty=0,previousManagement=0;for(const row of dps.rows){loyalty*=1+Math.max(0,s.loyaltyRate)/100;if(s.age+row.year<=65)loyalty+=(row.management-previousManagement)*.25;previousManagement=row.management;}
 const baseline=s.stress?compare({...s,stress:0}):null;
 return {s,dip,dps,points,annualTax,taxDetails:{dip:taxDetail(base,Math.min(available,s.own*12)),dps:taxDetail(base,Math.min(available,Math.max(0,s.own-(s.pensioner?0:1700))*12))},baseline:{dip:baseline?.dip.end.total??dip.end.total,dps:baseline?.dps.end.total??dps.end.total},support,eligible,excess,loyalty:s.loyalty&&!s.netReturns?loyalty:0,loyaltyEligible:eligible&&s.age+s.years>=65,difference:dip.end.total-dps.end.total};}
export function stressCases(raw){
 const s=cleanComparison(raw),cases=[['Bez krizového roku',0,0],['Propad na začátku',1,Math.min(2,s.years)],['Propad uprostřed',1,Math.max(1,Math.round(s.years/2))],['Propad před výběrem',1,s.years]];
 return cases.map(([label,stress,shockYear])=>{const r=compare({...s,stress,shockYear:shockYear||s.shockYear});return {label,year:shockYear,dip:r.dip.end.total,dps:r.dps.end.total,difference:r.difference};});
}


